('original:elementary--social-studies--3--local-government:elementary--social-studies--3--local-government--13',1,'{"question":"What is one reason local leaders ask residents for input?","choices":["Input can replace all planning.","Residents may understand neighborhood needs.","Residents can change federal laws on the spot.","Every resident will have the same idea."],"answer":1,"explanation":""}'::jsonb,'12ab74eba875a33324266a722a68c15e','official',NULL,NULL,'Grade 3 Social Studies — How Local Government Serves a Community'),
