('original:elementary--social-studies--4--early-american-history:elementary--social-studies--4--early-american-history--12',1,'{"question":"What might a tool found at a historic farm reveal?","choices":["the exact date of every event in the colony","which crops were never grown anywhere","how some work was done","the name of every person who touched it"],"answer":2,"explanation":""}'::jsonb,'04d7f61fc98956c8e30ddc7bdae350b7','official',NULL,NULL,'Grade 4 Social Studies — People and Change in Early America'),
('original:elementary--social-studies--4--early-american-history:elementary--social-studies--4--early-american-history--13',1,'{"question":"Which is a source Native communities may use to pass on knowledge?","choices":["oral histories shared by community members","only writing printed before 1500","only maps drawn by European settlers","only federal court lists"],"answer":0,"explanation":""}'::jsonb,'7febdd0e81a5c082c4789820d0a5e754','official',NULL,NULL,'Grade 4 Social Studies — People and Change in Early America'),
('original:elementary--social-studies--4--early-american-history:elementary--social-studies--4--early-american-history--14',1,'{"question":"Why compare a settler''s letter with a Native community''s account of an event?","choices":["All accounts must describe precisely the same details.","Each may describe different parts or viewpoints.","If they differ, neither can be studied.","One automatically cancels the other."],"answer":1,"explanation":""}'::jsonb,'ed160510929770f1a89318e6c639a701','official',NULL,NULL,'Grade 4 Social Studies — People and Change in Early America'),
('original:elementary--social-studies--4--early-american-history:elementary--social-studies--4--early-american-history--15',1,'{"question":"Which shows early Americans adapting to the climate where they lived?","choices":["building homes to keep out winter cold","using only one house design in every climate","building a home with no roof during each storm","ignoring the need for safe shelter"],"answer":0,"explanation":""}'::jsonb,'9db10479a15bdc87ac99bdd98a887a01','official',NULL,NULL,'Grade 4 Social Studies — People and Change in Early America'),
('original:elementary--social-studies--4--early-american-history:elementary--social-studies--4--early-american-history--16',1,'{"question":"What made Atlantic trade connect faraway communities?","choices":["All farms stood in one village.","Ships moved people and goods across the ocean.","The ocean always stopped trade entirely.","Colonies never bought goods from abroad."],"answer":1,"explanation":""}'::jsonb,'c539e4c626159d34c54fa90d020f02e3','official',NULL,NULL,'Grade 4 Social Studies — People and Change in Early America')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:elementary--social-studies--4--early-american-history:elementary--social-studies--4--early-american-history--17',1,'{"question":"A timeline shows a fort was built in 1754 and rebuilt in 1765. What happened first?","choices":["the fort was rebuilt","the order cannot be known","the original fort was built","both happened in 1765"],"answer":2,"explanation":""}'::jsonb,'e5dcc49060250ed4789d5d47b8015e77','official',NULL,NULL,'Grade 4 Social Studies — People and Change in Early America'),
('original:elementary--social-studies--4--early-american-history:elementary--social-studies--4--early-american-history--18',1,'{"question":"Why should you ask who made a map of early Ohio and when?","choices":["A person''s name makes the map exact.","The maker and date affect what the map can show.","Every old map shows all communities equally.","The date changes the distance between places."],"answer":1,"explanation":""}'::jsonb,'fc340ce313790533a7cced35ab778f8e','official',NULL,NULL,'Grade 4 Social Studies — People and Change in Early America'),
('original:elementary--social-studies--4--early-american-history:elementary--social-studies--4--early-american-history--19',1,'{"question":"Which work might involve learning a trade from a skilled person?","choices":["buying a printed book once","visiting a river for one hour","keeping a calendar with no job","apprenticing with a printer"],"answer":3,"explanation":""}'::jsonb,'23196dcd31163d1acdf6133499355210','official',NULL,NULL,'Grade 4 Social Studies — People and Change in Early America'),
('original:elementary--social-studies--4--early-american-history:elementary--social-studies--4--early-american-history--20',1,'{"question":"Which material best shows what the writer of a letter valued at the time?","choices":["the price of a new frame for the letter","what the writer chose to describe and ask about","the color of a library shelf","the colors of a modern folder"],"answer":1,"explanation":""}'::jsonb,'64a765c825d14ad89f9fe1d07349d1ba','official',NULL,NULL,'Grade 4 Social Studies — People and Change in Early America'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--1',1,'{"question":"Why is it more accurate to name a specific Native nation when describing its traditions?","choices":["Native nations never share any traditions.","All nations speak the same language.","Different nations have distinct histories and practices.","A tradition cannot belong to a living community."],"answer":2,"explanation":""}'::jsonb,'31a171735d8f8e4fda75b7417c3eafd9','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--2',1,'{"question":"Which is true of many Native nations today?","choices":["They only appear in historical stories.","They no longer teach their languages.","They have their own governments and living cultures.","They all share one government for every nation."],"answer":2,"explanation":""}'::jsonb,'2e319bdd368ca3d928534449e8569d7e','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--3',1,'{"question":"Which is the best primary choice for learning how a Native nation describes its own culture today?","choices":["a movie with no named nation","an old toy label","materials shared by that nation''s cultural office","a travel flyer without sources"],"answer":2,"explanation":""}'::jsonb,'8e0431b9c95726319c057e82f980047e','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--4',1,'{"question":"What does tribal sovereignty include?","choices":["the idea that every nation uses identical laws","a Native nation''s authority to govern itself","a rule making every community a museum","control of all foreign governments"],"answer":1,"explanation":""}'::jsonb,'b42f5486256073100261f85a6d93424b','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--5',1,'{"question":"Why might Native people describe the same river in more than one language?","choices":["Communities can have different languages and histories in a place.","A river''s name always comes from maps published today.","Each river can have only one name.","A language cannot describe natural places."],"answer":0,"explanation":""}'::jsonb,'172c74fbb28f43fa6e5b4ae41a77153f','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--6',1,'{"question":"Which name refers to a confederacy of Native nations also known as the Six Nations?","choices":["Thirteen Colonies","Haudenosaunee Confederacy","Ohio General Assembly","United States Congress"],"answer":1,"explanation":""}'::jsonb,'a2ea69b4406e3bd7ee301ee7c459a1db','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--7',1,'{"question":"Which nation works with the Myaamia Center to support the Myaamia language and culture?","choices":["Miami Tribe of Oklahoma","Navajo Nation","Cherokee Nation","Osage Nation"],"answer":0,"explanation":""}'::jsonb,'477209c1b60ba6211441852984078d31','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--8',1,'{"question":"Why do some Native communities support language programs?","choices":["to replace every language in the world","to help people learn and use their language across generations","to make books impossible to read","to keep people from speaking to their elders"],"answer":1,"explanation":""}'::jsonb,'bf6c9ec150cac9ea638452033a69834d','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--9',1,'{"question":"Which source best shows that Native culture continues in the present?","choices":["an unlabeled drawing made by a tourist long ago","a blank timeline ending in 1800","a recent interview with a Native artist about their current work","a sign with no date or author"],"answer":2,"explanation":""}'::jsonb,'1ad747be1e94e8c4b0ec94664eb6a7f8','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--10',1,'{"question":"What did the historic earthworks in Ohio require their builders to do?","choices":["use printed road signs from modern cities","organize and plan large building projects","wait for European machines to arrive","live without measuring space"],"answer":1,"explanation":""}'::jsonb,'af0f0c729581480193371480c79f0374','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--11',1,'{"question":"Which label accurately describes a group with historic connections to the Ohio River region?","choices":["Shawnee people","all French-speaking communities","every Native nation in North America","the British Parliament"],"answer":0,"explanation":""}'::jsonb,'c76fe37d16f05bf90bf09cdba0c16e17','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--12',1,'{"question":"If a museum label uses one word for all Native cultures, what is a good improvement?","choices":["remove the item''s date and place","change all names to “unknown” even when they are known","identify the nation and explain the item''s own context","label every object with the same maker"],"answer":2,"explanation":""}'::jsonb,'c7a4f9f66fc9b3ea093a153996f51e4e','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--13',1,'{"question":"Why can comparing historical housing designs show adaptation?","choices":["Every nation had identical weather and resources.","Homes show nothing about how people live.","All houses were temporary everywhere.","Different resources and climates can shape different designs."],"answer":3,"explanation":""}'::jsonb,'3efb879210dea95833ab2362951bb773','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--14',1,'{"question":"Which is a good way to handle a story that a community shares only in certain settings?","choices":["follow the community''s guidance","say the community has no stories","post it publicly without asking","write a different ending and call it original"],"answer":0,"explanation":""}'::jsonb,'d86149b8aaeec16c8aad813e86821d2c','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--15',1,'{"question":"What is one reason to study Native nations both before and after early contact with Europeans?","choices":["It keeps you from noticing change over time.","It shows every nation had the same experience.","It proves each nation stopped existing at first contact.","It shows histories that began earlier and continued through change."],"answer":3,"explanation":""}'::jsonb,'d905ba102d6ea26c6d78e08860fa58b9','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--16',1,'{"question":"What can a territory map and a present-day nation website show together?","choices":["historic places and present-day community life","exactly what every person in history thought","that communities have no ties to land","why all Native nations share one language"],"answer":0,"explanation":""}'::jsonb,'cee4e90ed2f44d1ab032213b1b70ee04','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--17',1,'{"question":"Which is an example of cultural knowledge that can be passed down?","choices":["what all people must eat on the same day","a random list of street numbers with no context","a rule that all nations tell the same stories","how and when to gather a food safely in a certain place"],"answer":3,"explanation":""}'::jsonb,'4faf837ca6dc2f8dda291d5cbe7a9740','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--18',1,'{"question":"What does a treaty show best on its own?","choices":["whether everyone freely agreed to it","that both sides always followed it","how everyone felt about it","what a written agreement says"],"answer":3,"explanation":""}'::jsonb,'16a2f5ea0d962f509b572151795c59b6','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--19',1,'{"question":"What could a school group do before using a design linked to a Native nation?","choices":["say it belongs to every nation","learn its purpose through sources from the nation and ask about permission","use it for any purpose without checking","copy it and invent a meaning"],"answer":1,"explanation":""}'::jsonb,'9ace39fc748270489af5702907f553e2','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--4--native-american-cultures:elementary--social-studies--4--native-american-cultures--20',1,'{"question":"Which is an accurate way to describe Native nations?","choices":["They belong only in the past.","They all have identical ways of choosing leaders.","They formed only after the U.S. became a country.","They have changed over time while maintaining distinct identities."],"answer":3,"explanation":""}'::jsonb,'6df7dde8dfc9027a7d37a4a438113935','official',NULL,NULL,'Grade 4 Social Studies — Native Nations, Places, and Living Cultures'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--1',1,'{"question":"What made some North American colonies useful to European trading nations?","choices":["They produced nothing to sell.","They were all already independent countries.","They never used ocean trade.","They supplied goods and bought imported products."],"answer":3,"explanation":""}'::jsonb,'3c3e90b31f59accc6468eb05c516d8d6','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--2',1,'{"question":"Which crop became important to the economy of colonial Virginia?","choices":["tea leaves","coffee","tobacco","bananas"],"answer":2,"explanation":""}'::jsonb,'7d0f82b8a765df3962d56d1632ced3d5','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--3',1,'{"question":"What made many colonial port towns good places for trade?","choices":["The towns were far from every river and ocean.","Ships could load and unload goods there.","Trade goods could only move on mountain paths.","Roads kept all goods away from the harbor."],"answer":1,"explanation":""}'::jsonb,'bb130d6923ee96aacfebc010745a1ea8','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--4',1,'{"question":"Which job makes a person an apprentice?","choices":["sailing past the town","learning printing while working with a skilled printer","reading a sign in a market","buying a newspaper at a shop"],"answer":1,"explanation":""}'::jsonb,'b6ec17f994d1ebc988e9a7fe4adce5c7','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--5',1,'{"question":"Which group often did forced labor on colonial plantations?","choices":["enslaved Africans and their descendants","all hired apprentices","elected assembly members as a group","all visiting traders"],"answer":0,"explanation":""}'::jsonb,'153234f24abb5e8bc02ff1865df9c28c','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--6',1,'{"question":"Why did families who moved to the English colonies have different experiences?","choices":["They all chose to move freely.","Their reasons, resources, and legal freedom differed.","They all settled in the same port at once.","They all received the same jobs and land."],"answer":1,"explanation":""}'::jsonb,'751ea483d9ce0993c31c4ef57d5a3457','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--7',1,'{"question":"What was a reason some English settlers chose parts of New England?","choices":["They were seeking the Pacific Ocean.","They planned to become independent in 1607.","They wanted to form communities around their religious beliefs.","They expected a tropical climate."],"answer":2,"explanation":""}'::jsonb,'d6189412d27004237db158263e87ca65','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--8',1,'{"question":"How could location affect what a colony traded?","choices":["Rivers made it impossible to travel.","Every colony sold the same crops.","Location changed the language of all people there immediately.","A harbor helped a colony send goods overseas."],"answer":3,"explanation":""}'::jsonb,'3b538e201657cfe08e13ea8bc3ea9d03','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--9',1,'{"question":"Which record best helps compare prices in two port towns?","choices":["dated shop account books from both towns","an undated map showing coastlines only","one town seal","a single recipe for stew"],"answer":0,"explanation":""}'::jsonb,'b47d4baec922432572174e0e2a4e6b69','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--10',1,'{"question":"What can a colony''s tax record help a researcher learn?","choices":["what settlers dreamed about","which listed items or people were taxed","how each person felt about the tax","the exact words people spoke at dinner"],"answer":1,"explanation":""}'::jsonb,'db08565416f11ef8c174b115e818216d','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--11',1,'{"question":"Which is an example of self-government under British rule?","choices":["some eligible colonists electing members of an assembly","the colonies forming the modern U.S. Supreme Court","every colonist voting in British Parliament","every royal decision being made by children"],"answer":0,"explanation":""}'::jsonb,'949eaa8135b7c4ef09c04685aff2b607','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--12',1,'{"question":"Why do historians distinguish indentured labor from slavery?","choices":["Both guaranteed equal pay and rights.","Neither was used in English colonies.","Both always allowed workers to leave freely.","Indentured service was for a term; slavery treated people as property."],"answer":3,"explanation":""}'::jsonb,'acc7c2442d70b8e57141775210565a0b','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--13',1,'{"question":"What links ships, merchants, and farms in colonial trade?","choices":["Merchants made all products aboard ships.","Farmers grew only enough to throw away.","Farm goods could be sold by merchants and carried by ship.","Ships never moved goods between places."],"answer":2,"explanation":""}'::jsonb,'4d709f8e54379336554d45ee3e4cc82e','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--14',1,'{"question":"Why might the same colony include more than one spoken language?","choices":["Ships could carry only English speakers.","Its laws required every person to speak only one language.","There were no Indigenous languages.","Residents came from different communities and places."],"answer":3,"explanation":""}'::jsonb,'3fc3a3769a191e8e5e03520122078d7a','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--15',1,'{"question":"Which comparison shows different colonial economies?","choices":["Every coastal and inland community had the same jobs.","Ships could reach every inland farm directly.","Port towns relied on trade; some inland communities relied more on farming.","Only inland communities used crops."],"answer":2,"explanation":""}'::jsonb,'2fb651939ae80e688b6ce5fee27943eb','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--16',1,'{"question":"What is a way to learn about a typical day for enslaved people?","choices":["compare accounts of formerly enslaved people and records about their lives","assume every family worked under the same conditions","read only a plantation owner''s price list","use only a map of modern sports stadiums"],"answer":0,"explanation":""}'::jsonb,'ccb649771f6fd012f4260204b111fa9e','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--17',1,'{"question":"Which would be a secondary source on a colonial settlement?","choices":["a land deed from that time","a letter mailed from the settlement","a diary kept by a settler","a modern historian''s explanation based on old records"],"answer":3,"explanation":""}'::jsonb,'d95ed6285e326ae0d919c1313d17e95d','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--18',1,'{"question":"Why could relations between Native nations and colonists change over time?","choices":["No one moved or traded after first contact.","Trading, land pressure, and alliances could change their choices.","Everyone spoke the same language from the start.","All communities always agreed on who owned the land."],"answer":1,"explanation":""}'::jsonb,'d1fb0a889aedb495188615f4cf0e49e7','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--19',1,'{"question":"Which type of location often encouraged shipbuilding in New England?","choices":["an inland valley cut off from waterways","a treeless desert with no trade","a coast with harbors and access to timber","a mountaintop far from any rivers"],"answer":2,"explanation":""}'::jsonb,'5ee5631d17aba5b982827b344c6daf6f','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--colonial-america:elementary--social-studies--5--colonial-america--20',1,'{"question":"What is one question a colonial map by itself usually cannot answer?","choices":["How did different people feel about a new law?","Which feature is represented by the river symbol?","What direction was the harbor from town?","Where is the marked road?"],"answer":0,"explanation":""}'::jsonb,'343592f92f90d5780e3ce8618870ef4b','official',NULL,NULL,'Grade 5 Social Studies — Daily Life and Choices in Colonial America'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--1',1,'{"question":"What did many colonists mean by “no taxation without representation”?","choices":["They wanted to end all elections in the colonies.","They wanted taxes set only by France.","They objected to taxes passed by a legislature in which they had no elected representatives.","They claimed there were no merchants to tax."],"answer":2,"explanation":""}'::jsonb,'4b51061ae3d9d6fe346eaf0865a44d6e','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--2',1,'{"question":"What did the Stamp Act tax?","choices":["only ocean water","many printed materials and legal papers","only farm-grown apples","all shoes from Mexico"],"answer":1,"explanation":""}'::jsonb,'04a91e83f16ed992851ead73e6c24d24','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--3',1,'{"question":"Why did protesters dump tea into Boston Harbor in 1773?","choices":["to open a shipping business","to celebrate a completed peace treaty","to raise money for a tea shop","to oppose British tea policy and taxation"],"answer":3,"explanation":""}'::jsonb,'72915b4ca4252ff228945428e6e70e97','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--4',1,'{"question":"Where did the first battles of the Revolutionary War take place in 1775?","choices":["Detroit and New Orleans","Lexington and Concord","Jamestown and Plymouth","Yorktown and Paris"],"answer":1,"explanation":""}'::jsonb,'4cdbeab94a667f119b61e40f46a8373c','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--5',1,'{"question":"What did the Declaration of Independence announce?","choices":["The war was already over.","The colonies asked to join Parliament.","The colonies declared loyalty to France.","The colonies claimed to be independent states."],"answer":3,"explanation":""}'::jsonb,'593bac69a62fb317260e30fd60fcabde','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--6',1,'{"question":"When did the Continental Congress adopt the Declaration of Independence?","choices":["1765","1787","1783","1776"],"answer":3,"explanation":""}'::jsonb,'9f608f5b4eb3d30787035fcfbe87be65','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--7',1,'{"question":"Who served as commander in chief of the Continental Army?","choices":["Benjamin Franklin","Thomas Jefferson","George Washington","King George III"],"answer":2,"explanation":""}'::jsonb,'01c78ad7ba677d306dea75dd93f2e47c','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--8',1,'{"question":"Which people wanted the colonies to remain part of Britain?","choices":["Loyalists","members of every Native nation","Patriots as a group","French soldiers"],"answer":0,"explanation":""}'::jsonb,'53de23b0213aaca1d10cea824bd0e32c','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--9',1,'{"question":"Which country formally allied with the United States in 1778?","choices":["Germany","Britain","France","Canada"],"answer":2,"explanation":""}'::jsonb,'bed86b56ff509de328bd16107e566939','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--10',1,'{"question":"What agreement formally ended the war between Britain and the United States in 1783?","choices":["U.S. Constitution","Treaty of Paris","Stamp Act","Mayflower Compact"],"answer":1,"explanation":""}'::jsonb,'345638087dc1e84c71b0d7f958c76d64','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--11',1,'{"question":"Which event came before Britain agreed to peace in 1783?","choices":["The Louisiana Purchase was completed.","British forces surrendered at Yorktown.","Ohio became a state.","The U.S. Constitution was written in 1787."],"answer":1,"explanation":""}'::jsonb,'d14336df1bf48985067e771b83c5541b','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--12',1,'{"question":"Why might a merchant stop buying goods from Britain before the war?","choices":["to join a boycott in protest of British policies","to support higher taxes on the same goods","to vote in British Parliament","to make those goods cheaper in Britain directly"],"answer":0,"explanation":""}'::jsonb,'e1da7f343e95b7b64dd42346799f3d9b','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--13',1,'{"question":"Which source could show how one Loyalist described the conflict?","choices":["a recent map with no comments","a modern price label for tea","a fictional story about a future election","a letter written by a Loyalist during the war"],"answer":3,"explanation":""}'::jsonb,'6fc885034645f352a6b78a3cd5ef8a67','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--14',1,'{"question":"Why were perspectives in the colonies different during the Revolution?","choices":["All Patriots wanted Britain to keep ruling.","No one knew which side their leaders chose.","People had different loyalties and risks.","Everyone had equal rights and agreed on what to do."],"answer":2,"explanation":""}'::jsonb,'d6d2d02fe6de647e8d265a3a525d7258','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--15',1,'{"question":"What goal did the Declaration express even though many people were still enslaved?","choices":["the end of all government","the claim that slavery had already ended everywhere","a ban on all writing","the ideal that people have equal rights"],"answer":3,"explanation":""}'::jsonb,'14b71d26c2da250093c4e547be04c3cf','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--16',1,'{"question":"Why did some enslaved people seek freedom through wartime service or escape?","choices":["They were trying to gain liberty for themselves and their families.","They already had the same legal freedom as everyone else.","They were required to pay taxes as members of Parliament.","All armies promised safety and freedom to everyone."],"answer":0,"explanation":""}'::jsonb,'d17b4f901807617af7ec747afc3c3a5c','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--17',1,'{"question":"Why did some Native nations make alliances during the war?","choices":["They all wanted the new states to expand onto their lands.","To protect their lands and interests in a changing conflict.","They had no lands or governments to protect.","All Native nations made the same choice together."],"answer":1,"explanation":""}'::jsonb,'048ef04e2000e994a21b8311b0258cdb','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--18',1,'{"question":"What did a battle map help military leaders decide?","choices":["where to move troops and supplies","the price of tea in every town","what each soldier thought","who would write all future laws"],"answer":0,"explanation":""}'::jsonb,'5a46a1aa722aeaedbbbae7d79c67979a','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--19',1,'{"question":"How did French support help the Americans at Yorktown?","choices":["French representatives wrote Britain''s surrender before the battle began.","France fought for Britain at Yorktown.","French ships and troops helped block and pressure British forces.","French ships stopped American troops from reaching the area."],"answer":2,"explanation":""}'::jsonb,'d384684e21e04d8d9bed15f88b245fbb','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--american-revolution:elementary--social-studies--5--american-revolution--20',1,'{"question":"Which timeline is in the correct order?","choices":["Boston Tea Party → Declaration of Independence → Treaty of Paris","Declaration of Independence → Boston Tea Party → Treaty of Paris","Declaration of Independence → Treaty of Paris → Boston Tea Party","Treaty of Paris → Boston Tea Party → Declaration of Independence"],"answer":0,"explanation":""}'::jsonb,'0be1136876bc3e73aa70cde0b5d11a85','official',NULL,NULL,'Grade 5 Social Studies — Causes and Consequences of the American Revolution'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--1',1,'{"question":"What is the main job of the U.S. Constitution?","choices":["lists daily weather forecasts","sets store prices in every state","sets out how the federal government works","announces the first battles of the Revolution"],"answer":2,"explanation":""}'::jsonb,'a87f3f18a996056774ac97a2f902678b','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--2',1,'{"question":"Which branch of the federal government makes laws?","choices":["military alone","legislative","executive","judicial"],"answer":1,"explanation":""}'::jsonb,'0da1a3c69d981714fe56e0404c95650f','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--3',1,'{"question":"Which branch carries out federal laws?","choices":["judicial","executive","town council","legislative"],"answer":1,"explanation":""}'::jsonb,'955d4722d359cd05e9654cb7e9867043','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--4',1,'{"question":"Which branch decides court cases about federal laws?","choices":["legislative only","judicial","state highway department","executive only"],"answer":1,"explanation":""}'::jsonb,'e7446c78958ebd37fb8a401a7efba81f','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--5',1,'{"question":"Which two bodies form the U.S. Congress?","choices":["President and Supreme Court","House of Representatives and Senate","President and House of Representatives","Supreme Court and Senate"],"answer":1,"explanation":""}'::jsonb,'2998cecf100702d5b4baab077ef22ffd','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--6',1,'{"question":"What name is given to the first ten amendments?","choices":["Declaration of Independence","Treaty of Paris","Articles of Confederation","Bill of Rights"],"answer":3,"explanation":""}'::jsonb,'cb1ae2363803010ad313c2e615b5d217','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--7',1,'{"question":"What is an amendment?","choices":["an official change or addition to the Constitution","a court building","a yearly budget alone","a political party"],"answer":0,"explanation":""}'::jsonb,'c51ed6bf4b773d91d7b460f905deb73b','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--8',1,'{"question":"Residents write to Congress asking it to change a law. Which First Amendment freedom does this illustrate?","choices":["the right to serve on a jury","the right to run for every office","the right to petition the government","the right to own a home"],"answer":2,"explanation":""}'::jsonb,'cf361533871814fbc66f13ce67584cdd','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--9',1,'{"question":"What does it mean that the president can veto a bill?","choices":["The president can write laws without Congress in every case.","The president can appoint every governor.","The president can reject a bill passed by Congress.","The president can erase all court decisions."],"answer":2,"explanation":""}'::jsonb,'6f4fe3e748954ccdff05505d1f5ea5bc','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--10',1,'{"question":"Which is an example of a check on government power?","choices":["A city mayor can replace Congress.","Every branch approves its own powers without limits.","The same person runs every branch for life.","Congress can override a presidential veto with enough votes."],"answer":3,"explanation":""}'::jsonb,'4298b71dca04dae169dc3a37d7c0cd84','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--11',1,'{"question":"What does federalism divide power between?","choices":["the national and state governments","the Senate and House alone","different grades at one school","only two national courts"],"answer":0,"explanation":""}'::jsonb,'78abbb7ebf80d3833fda16d498f7019e','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--12',1,'{"question":"Which power is assigned to the federal government?","choices":["write each city''s parking rules","assign city library cards","coin U.S. money","set hours for a local playground"],"answer":2,"explanation":""}'::jsonb,'16f3a90a4acd8573096051551388e14d','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--13',1,'{"question":"Which action most clearly involves a state power?","choices":["setting rules for state driver''s licenses","coining U.S. money","declaring war on another country","making treaties with other countries"],"answer":0,"explanation":""}'::jsonb,'f47a00add764835d597664bfb18b7edb','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--14',1,'{"question":"Why are elections important in a representative system?","choices":["Eligible voters can choose people to act for them.","Leaders must inherit office.","Courts select all voters.","Only officials choose their successors."],"answer":0,"explanation":""}'::jsonb,'80994b26000f9fda535d4ad03cca5486','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--15',1,'{"question":"What earlier national frame of government preceded the U.S. Constitution?","choices":["Treaty of Guadalupe Hidalgo","Articles of Confederation","Gettysburg Address","Bill of Rights"],"answer":1,"explanation":""}'::jsonb,'f0e8dbcddc8277cc7ae3720d8d488da6','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--16',1,'{"question":"What is one role of the U.S. Supreme Court?","choices":["decide cases involving the Constitution","lead local police departments","write all federal laws from scratch","run every state school"],"answer":0,"explanation":""}'::jsonb,'e42a0beba483108a053b601d4b40f5d2','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--17',1,'{"question":"Which document announced independence, rather than setting up today''s three federal branches?","choices":["U.S. Constitution","Bill of Rights","a state driver''s handbook","Declaration of Independence"],"answer":3,"explanation":""}'::jsonb,'993f26b84d968f83fa132a32ba10eaf1','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--18',1,'{"question":"What idea is introduced by “We the People” in the Constitution?","choices":["There can be only one branch.","States have no people of their own.","Government authority is based on the people.","The president alone is the source of all laws."],"answer":2,"explanation":""}'::jsonb,'7d8ccab8414929603b927389b6b92062','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--19',1,'{"question":"Why separate power among the branches?","choices":["so federal laws never change","so citizens never need representatives","so every branch has exactly the same tasks","to limit the power any one branch can use by itself"],"answer":3,"explanation":""}'::jsonb,'4afe661d8a396a624204ca49ef86bda8','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--u-s-government-foundations:elementary--social-studies--5--u-s-government-foundations--20',1,'{"question":"What source should you use first to check which branch has a named constitutional power?","choices":["a sports article","a physical map of North America","an unsigned rumor","the text of the U.S. Constitution"],"answer":3,"explanation":""}'::jsonb,'31b344c03b0d076fcd39dfb285349c1f','official',NULL,NULL,'Grade 5 Social Studies — Foundations of U.S. Government'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--1',1,'{"question":"What did the Louisiana Purchase do in 1803?","choices":["ended the American Revolution","added a large territory to the United States through an agreement with France","created the first English colony","gave Ohio to France"],"answer":1,"explanation":""}'::jsonb,'43f4b7470ac92fe78af6beef835ad5d7','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--2',1,'{"question":"What did Lewis and Clark do after the Louisiana Purchase?","choices":["lead the Constitutional Convention","travel and record information on a western expedition","build the first U.S. railroad across the country","write the Declaration of Independence"],"answer":1,"explanation":""}'::jsonb,'cb9175b63b442125febf9f2af8b075e3','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--3',1,'{"question":"How did Sacagawea help the expedition?","choices":["She built a railroad ahead of them.","She wrote the purchase agreement with France.","She interpreted and helped the group communicate and travel.","She was president during the journey."],"answer":2,"explanation":""}'::jsonb,'464c8e7b60f0479ce6267d90b81a6088','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--4',1,'{"question":"Why is “empty land” inaccurate for much of the area settlers traveled into?","choices":["No maps described any western places.","All the land was under ocean water.","People could not live anywhere west of the Mississippi.","Native nations already lived there and governed their communities."],"answer":3,"explanation":""}'::jsonb,'ac2bfd41a996677e5c9c7309186c4dc6','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--5',1,'{"question":"What was one reason families used the Oregon Trail?","choices":["to return from Europe by ship","to build the first cities near the Atlantic coast","to reach Boston Harbor","to reach new homes and farmland in the West"],"answer":3,"explanation":""}'::jsonb,'59093ad02c99bdb2f338cb6c09355eb8','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--6',1,'{"question":"What is one hardship travelers could face on overland trails?","choices":["illness and difficult river crossings","a train station in every valley","ocean tides at every campsite","hotel rooms already booked each night"],"answer":0,"explanation":""}'::jsonb,'b162a5023ea428d6d315fe6a224b0366','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--7',1,'{"question":"What did the Indian Removal Act of 1830 help the federal government do?","choices":["make western settlements independent countries","force many Native people from their homelands","create voting rights for all Native people","return every taken acre to Native nations"],"answer":1,"explanation":""}'::jsonb,'a05ea44a69f83ce65a444acc39daed77','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--8',1,'{"question":"What was the Trail of Tears?","choices":["a celebration welcoming people home","a voluntary vacation route","forced removal in which many Cherokee and other Native people suffered and died","the route of the first coast-to-coast railroad"],"answer":2,"explanation":""}'::jsonb,'5e6344d967147ae59b9efeb3abe3b0ee','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--9',1,'{"question":"Which legal document transferred large areas from Mexico to the United States after the Mexican-American War?","choices":["Mayflower Compact","U.S. Bill of Rights","Treaty of Guadalupe Hidalgo","Treaty of Paris of 1783"],"answer":2,"explanation":""}'::jsonb,'815383226f8476f9ef26d7ccee37522b','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--10',1,'{"question":"What drew many newcomers to California in 1849?","choices":["the opening of the Erie Canal in California","the discovery of gold","the first flight across the Pacific","the founding of Jamestown"],"answer":1,"explanation":""}'::jsonb,'9c3897cbb04b5e6a17cd9e2d93af3a1d','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--11',1,'{"question":"What changed when the first transcontinental railroad was completed in 1869?","choices":["The United States stopped trading by rail.","Native communities gained back all taken land.","All journeys still took exactly as long as wagon trips.","People and goods could travel across much of the country faster."],"answer":3,"explanation":""}'::jsonb,'92e7afeb94eb437a7ac5616c19aacb67','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--12',1,'{"question":"Which groups labored on the first transcontinental railroad?","choices":["only people who had served in the Continental Congress","workers who included many Chinese and Irish immigrants","only state governors","only British veterans of the Revolution"],"answer":1,"explanation":""}'::jsonb,'731ea3c4f26b948e915355598e28bec0','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--13',1,'{"question":"What idea was called Manifest Destiny?","choices":["a Native nation''s general agreement to give up its lands","a treaty requiring the U.S. to stop all expansion","a belief used to justify U.S. expansion across the continent","a plan to move all western towns east"],"answer":2,"explanation":""}'::jsonb,'7f9a938098f732686692d2c9b17be01f','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--14',1,'{"question":"Which source best shows the experience of a person on an overland trail?","choices":["a diary by a traveler during the journey","a map of today''s airports alone","a new calendar with no notes","a modern poster for a train ride in another country"],"answer":0,"explanation":""}'::jsonb,'1e13257906c198fc5a213e2bc13bfe90','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--15',1,'{"question":"Why should a historian compare a settler''s letter with a Native nation''s account?","choices":["Only sources written by settlers can describe the event.","Both sources must give the same reason for moving.","Expansion meant different things to people it affected.","Comparing them makes dates unimportant."],"answer":2,"explanation":""}'::jsonb,'86e6d8674b7b794e24af5d9f2ecfcfa7','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences'),
('original:elementary--social-studies--5--westward-expansion:elementary--social-studies--5--westward-expansion--16',1,'{"question":"What did the Homestead Act offer to eligible applicants who met its conditions?","choices":["a way to claim some federal land","the right to remove any border they wanted","a free ship to Europe","a job building any railroad"],"answer":0,"explanation":""}'::jsonb,'39aa9ed188e7e05c151d02db5b2bfde3','official',NULL,NULL,'Grade 5 Social Studies — Westward Expansion and Its Consequences')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
