('original:elementary--general-knowledge-and-life-skills--2--digital-citizenship:elementary--general-knowledge-and-life-skills--2--digital-citizenship--10',1,'{"question":"An unverified post says the library is closed. What source should you check?","choices":["the library''s own website or phone line","the username with the most emojis","an unrelated game page","the oldest forwarded message"],"answer":0,"explanation":""}'::jsonb,'5236a626568dfc859516fde220030a26','official',NULL,NULL,'Grade 2 Life Skills — Making Safe and Kind Choices Online'),
('original:elementary--general-knowledge-and-life-skills--2--digital-citizenship:elementary--general-knowledge-and-life-skills--2--digital-citizenship--11',1,'{"question":"What does a digital footprint include?","choices":["your device''s weight","traces left by things people do online","only words written on paper","only shoeprints near a computer"],"answer":1,"explanation":""}'::jsonb,'a5b0285874333e7c817b1e686268b1fe','official',NULL,NULL,'Grade 2 Life Skills — Making Safe and Kind Choices Online'),
('original:elementary--general-knowledge-and-life-skills--2--digital-citizenship:elementary--general-knowledge-and-life-skills--2--digital-citizenship--12',1,'{"question":"Why think before posting?","choices":["Posts never affect anyone else.","Other people may copy or share what you post.","Deleting a post always removes every copy.","Posts are always visible only to you."],"answer":1,"explanation":""}'::jsonb,'1394f976708923290c81e3e2096b808d','official',NULL,NULL,'Grade 2 Life Skills — Making Safe and Kind Choices Online'),
('original:elementary--general-knowledge-and-life-skills--2--digital-citizenship:elementary--general-knowledge-and-life-skills--2--digital-citizenship--13',1,'{"question":"What should you do if a username includes your full name and birth date?","choices":["post the birth date in more chats","include your home address too","make the name your password","ask a trusted adult about using a safer name"],"answer":3,"explanation":""}'::jsonb,'248a169a67bd209e500a297a85e4ab72','official',NULL,NULL,'Grade 2 Life Skills — Making Safe and Kind Choices Online'),
('original:elementary--general-knowledge-and-life-skills--2--digital-citizenship:elementary--general-knowledge-and-life-skills--2--digital-citizenship--14',1,'{"question":"Which is a good first step if a pop-up asks you to download something unexpected?","choices":["press every button","announce your password","download the file on a friend''s device","stop and ask a trusted adult"],"answer":3,"explanation":""}'::jsonb,'a653b0a6c8604cdc332e219ce303ff27','official',NULL,NULL,'Grade 2 Life Skills — Making Safe and Kind Choices Online'),
('original:elementary--general-knowledge-and-life-skills--2--digital-citizenship:elementary--general-knowledge-and-life-skills--2--digital-citizenship--15',1,'{"question":"You use a drawing someone else made in a class project. What is responsible?","choices":["claim you drew it","sell it as your own work","follow permission rules and credit the creator","erase the artist''s name and repost it"],"answer":2,"explanation":""}'::jsonb,'8f4b72d7241a02cf885daa39337a61ba','official',NULL,NULL,'Grade 2 Life Skills — Making Safe and Kind Choices Online'),
('original:elementary--general-knowledge-and-life-skills--2--digital-citizenship:elementary--general-knowledge-and-life-skills--2--digital-citizenship--16',1,'{"question":"Someone you met only in a game asks to meet in person. What should you do?","choices":["go alone","send them your school schedule","tell a trusted adult and do not arrange a meeting yourself","agree to keep it secret"],"answer":2,"explanation":""}'::jsonb,'497499a0d6196b8cc16cc763bd5e7c0e','official',NULL,NULL,'Grade 2 Life Skills — Making Safe and Kind Choices Online'),
('original:elementary--general-knowledge-and-life-skills--2--digital-citizenship:elementary--general-knowledge-and-life-skills--2--digital-citizenship--17',1,'{"question":"What helps when an online message is hard to understand?","choices":["respond with an insult","immediately share it with everyone","ask what the person meant in a polite way","assume it can only mean one thing"],"answer":2,"explanation":""}'::jsonb,'4c46e326d6532dbc32ab4f5478c64e77','official',NULL,NULL,'Grade 2 Life Skills — Making Safe and Kind Choices Online'),
('original:elementary--general-knowledge-and-life-skills--2--digital-citizenship:elementary--general-knowledge-and-life-skills--2--digital-citizenship--18',1,'{"question":"Which choice helps you balance device time with rest?","choices":["keep using it while crossing a street","take a break when the agreed time is up","ignore all break reminders","use the device through bedtime secretly"],"answer":1,"explanation":""}'::jsonb,'b6a8fdd3ed0ec4e7290febb0738e52ff','official',NULL,NULL,'Grade 2 Life Skills — Making Safe and Kind Choices Online'),
('original:elementary--general-knowledge-and-life-skills--2--digital-citizenship:elementary--general-knowledge-and-life-skills--2--digital-citizenship--19',1,'{"question":"What should you do if a chat message says it came from your teacher and requests your password?","choices":["check with the teacher another way and keep your password private","put the password in a public channel","send the password because the name looks right","ask a classmate to send theirs too"],"answer":0,"explanation":""}'::jsonb,'b3059272efc08925097143c63d2cbdfa','official',NULL,NULL,'Grade 2 Life Skills — Making Safe and Kind Choices Online'),
('original:elementary--general-knowledge-and-life-skills--2--digital-citizenship:elementary--general-knowledge-and-life-skills--2--digital-citizenship--20',1,'{"question":"What helps you secure your own account if you think someone else used it?","choices":["reuse the same password everywhere","remove all protection","tell a trusted adult and ask for help updating the password","hide the problem and share the account again"],"answer":2,"explanation":""}'::jsonb,'1c9fe35ab571b5064f6a7d13cbafa449','official',NULL,NULL,'Grade 2 Life Skills — Making Safe and Kind Choices Online'),
